core_prepare_sql:
SET threads=1; SET memory_limit='64MB'; SET preserve_insertion_order=false;
SET temp_directory='$WORK_DIR/prepare-spill'; SET enable_profiling='json'; SET profiling_output='$WORK_DIR/prepare-profile.json';
COPY (SELECT DISTINCT ((hash(i) & 9223372036854775807::UBIGINT) << 1) k FROM range(8000000)t(i) ORDER BY k)
TO '$WORK_DIR/keys.csv' (HEADER false);
